begin;
select plan(25);
select set_config('test.owner',gen_random_uuid()::text,true);
select set_config('test.admin',gen_random_uuid()::text,true);
select set_config('test.client',gen_random_uuid()::text,true);
select set_config('test.appointment',gen_random_uuid()::text,true);
insert into auth.users(id,email,raw_user_meta_data) values(current_setting('test.owner')::uuid,'p-'||current_setting('test.owner')||'@example.test','{}'),(current_setting('test.admin')::uuid,'p-'||current_setting('test.admin')||'@example.test','{}');
insert into public.user_roles select current_setting('test.owner')::uuid,id from public.roles where code='OWNER';
insert into public.user_roles select current_setting('test.admin')::uuid,id from public.roles where code='ADMIN';
insert into public.clients(id,first_name) values(current_setting('test.client')::uuid,'Fixture pagos');
insert into public.appointments(id,client_id,starts_at,ends_at,status,total_price,created_by) values(current_setting('test.appointment')::uuid,current_setting('test.client')::uuid,'2020-01-06 12:00+00','2020-01-06 13:00+00','COMPLETED',100.35,current_setting('test.owner')::uuid);
select set_config('test.input',jsonb_build_object('appointment_id',current_setting('test.appointment'),'type','BALANCE','method','CASH','amount','20.10','request_id',gen_random_uuid())::text,true);
select set_config('request.jwt.claim.sub',current_setting('test.admin'),true);
set local role authenticated;
select set_config('test.payment',public.register_payment(current_setting('test.input')::jsonb)->>'id',true);
select is(public.get_payment(current_setting('test.payment')::uuid)->>'status','PENDING','Registro no verifica efectivo');
select is(public.get_payment(current_setting('test.payment')::uuid)->>'created_by',current_setting('test.admin'),'Autor de servidor');
select is(public.appointment_payment_summary(current_setting('test.appointment')::uuid)->>'outstanding','100.35','Pendiente no descuenta saldo');
select is(public.appointment_payment_summary(current_setting('test.appointment')::uuid)->>'pending','20.10','Pendiente se muestra separado');
select is(public.register_payment(current_setting('test.input')::jsonb)->>'id',current_setting('test.payment'),'Reintento devuelve mismo registro');
select throws_ok($$select public.verify_payment(current_setting('test.payment')::uuid,1)$$,'42501',null,'ADMIN no verifica efectivo');
select throws_ok($$select public.reject_payment(current_setting('test.payment')::uuid,1,'No recibido')$$,'42501',null,'ADMIN no rechaza');
select throws_ok($$select public.register_payment(current_setting('test.input')::jsonb||'{"amount":"0"}')$$,'22023',null,'Cero no permitido');
select throws_ok($$select public.register_payment(current_setting('test.input')::jsonb||'{"amount":"1.234"}')$$,'22023',null,'Sin redondeo implícito');
select throws_ok($$select public.register_payment(current_setting('test.input')::jsonb||'{"status":"PAID"}')$$,'22023',null,'No forjar estado');
select throws_ok($$insert into public.payments(appointment_id,type,method,amount,created_by,request_id) values(current_setting('test.appointment')::uuid,'BALANCE','CASH',1,current_setting('test.admin')::uuid,gen_random_uuid())$$,'42501',null,'INSERT directo revocado');
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.owner'),true);
set local role authenticated;
select public.open_cash('0',gen_random_uuid());
select lives_ok($$select public.verify_payment(current_setting('test.payment')::uuid,1)$$,'OWNER verifica');
select is(public.appointment_payment_summary(current_setting('test.appointment')::uuid)->>'confirmed','20.10','Suma confirmada exacta');
select is(public.appointment_payment_summary(current_setting('test.appointment')::uuid)->>'outstanding','80.25','Saldo decimal exacto');
select throws_ok($$select public.verify_payment(current_setting('test.payment')::uuid,1)$$,'40001',null,'Versión vieja rechazada');
select throws_ok($$select public.verify_payment(current_setting('test.payment')::uuid,2)$$,'22023',null,'No confirmar dos veces');
reset role;
select throws_ok($$update public.appointments set total_price=1 where id=current_setting('test.appointment')::uuid$$,'22023',null,'Total no baja de lo recibido');
select throws_ok($$insert into public.payments(appointment_id,type,method,amount,created_by,request_id) values(current_setting('test.appointment')::uuid,'BALANCE','CASH','NaN',current_setting('test.owner')::uuid,gen_random_uuid())$$,'23514',null,'NaN rechazado por constraint');
select throws_ok($$insert into public.payments(appointment_id,type,method,amount,created_by,request_id) values(current_setting('test.appointment')::uuid,'BALANCE','CASH',null,current_setting('test.owner')::uuid,gen_random_uuid())$$,'23502',null,'Importe NOT NULL');
select throws_ok($$insert into public.payments(appointment_id,type,method,status,amount,created_by,request_id) values(current_setting('test.appointment')::uuid,'BALANCE','CASH','PAID',1,current_setting('test.owner')::uuid,gen_random_uuid())$$,'23514',null,'PAID exige verificador/fecha');
select throws_ok($$insert into public.payments(appointment_id,type,method,amount,created_by,request_id,proof_url) values(current_setting('test.appointment')::uuid,'BALANCE','CASH',1,current_setting('test.owner')::uuid,gen_random_uuid(),'https://example.test')$$,'23514',null,'No almacenar URL de comprobante');
select set_config('request.jwt.claim.sub','',true);
set local role authenticated;
select is((select count(*)::integer from public.payments where appointment_id=current_setting('test.appointment')::uuid),0,'RLS sin identidad');
select throws_ok($$select public.appointment_payment_summary(current_setting('test.appointment')::uuid)$$,'42501',null,'Sin identidad no consulta resumen');
reset role;
set local role anon;
select throws_ok($$select public.search_payments()$$,'42501',null,'Anon no ejecuta listado');
select throws_ok($$select public.get_payment(current_setting('test.payment')::uuid)$$,'42501',null,'Anon no obtiene detalle');
reset role;
select * from finish();
rollback;
